// Post-processes the report `ori eval` writes for `bun run bakeoff`: drops the per-run
// log (the "Run on" line and the "Run history" section) and adds a header pointing to
// the app's own scores. Usage: bun scripts/clean-bakeoff-report.ts docs/model-bakeoff.md

const HEADER =
  "> Generated by `bun run bakeoff` (Ori's `ori eval` report). " +
  "Its Correctness column counts completed runs; the app's own scores are in the README's " +
  "[Model choice](../README.md#model-choice) section.";

export function cleanBakeoffReport(markdown: string): string {
  const kept: string[] = [];
  let inRunHistory = false;
  for (const line of markdown.split("\n")) {
    if (line.startsWith("## ")) inRunHistory = line.trim() === "## Run history";
    if (inRunHistory) continue;
    if (/^Run on \S+\.?\s*$/.test(line)) continue;
    if (line.startsWith("> Generated by")) continue;
    kept.push(line);
  }
  const body = kept.join("\n").replace(/\n{3,}/g, "\n\n").trimStart();
  return `${HEADER}\n\n${body}`;
}

if (import.meta.main) {
  const path = process.argv[2];
  if (!path) {
    console.error("usage: bun scripts/clean-bakeoff-report.ts <report.md>");
    process.exit(1);
  }
  const file = Bun.file(path);
  await Bun.write(path, cleanBakeoffReport(await file.text()));
}
